<?php
declare(strict_types=1);
namespace App\Repositories;
use App\Core\Database;

final class PakistanErpRepository
{
    public function __construct(private readonly Database $db){}
    public function db():Database{return $this->db;}

    public function guardians(int $institute):array{return $this->db->query("SELECT g.*,COUNT(gs.student_id) child_count,GROUP_CONCAT(gs.student_id ORDER BY gs.student_id) student_ids FROM guardians g LEFT JOIN guardian_students gs ON gs.guardian_id=g.id WHERE g.institute_id=:i GROUP BY g.id ORDER BY g.name",['i'=>$institute])->fetchAll();}
    public function deactivateGuardian(int$id,int$i):bool{return$this->db->query('UPDATE guardians SET status="inactive",updated_at=:u WHERE id=:id AND institute_id=:i',['u'=>date('Y-m-d H:i:s'),'id'=>$id,'i'=>$i])->rowCount()>0;}
    public function guardian(int $id,int $institute):?array{$r=$this->db->query('SELECT * FROM guardians WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$institute])->fetch();return $r?:null;}
    public function guardianByUser(int $user):?array{$r=$this->db->query('SELECT g.* FROM guardian_accounts ga JOIN guardians g ON g.id=ga.guardian_id WHERE ga.user_id=:u LIMIT 1',['u'=>$user])->fetch();return $r?:null;}
    public function guardianChildren(int $guardian,int $institute):array{return $this->db->query('SELECT s.*,c.name class_name,cs.name section_name FROM guardian_students gs JOIN guardians g ON g.id=gs.guardian_id JOIN students s ON s.id=gs.student_id LEFT JOIN classes c ON c.id=s.class_id LEFT JOIN class_sections cs ON cs.id=s.section_id WHERE gs.guardian_id=:g AND g.institute_id=:i AND s.institute_id=:i2 ORDER BY s.student_name',['g'=>$guardian,'i'=>$institute,'i2'=>$institute])->fetchAll();}
    public function guardianChild(int $guardian,int $student,int $institute):?array{$r=$this->db->query('SELECT s.*,c.name class_name FROM guardian_students gs JOIN guardians g ON g.id=gs.guardian_id JOIN students s ON s.id=gs.student_id LEFT JOIN classes c ON c.id=s.class_id WHERE gs.guardian_id=:g AND gs.student_id=:s AND g.institute_id=:i AND s.institute_id=:i2',['g'=>$guardian,'s'=>$student,'i'=>$institute,'i2'=>$institute])->fetch();return $r?:null;}
    public function saveGuardian(?int$id,int$i,array$d):int{$now=date('Y-m-d H:i:s');if($id){$this->db->query('UPDATE guardians SET name=:name,relationship=:relationship,cnic=:cnic,mobile=:mobile,email=:email,address=:address,status=:status,updated_at=:u WHERE id=:id AND institute_id=:i',$d+['u'=>$now,'id'=>$id,'i'=>$i]);return$id;}$this->db->query('INSERT INTO guardians(institute_id,name,relationship,cnic,mobile,email,address,status,created_at,updated_at) VALUES(:i,:name,:relationship,:cnic,:mobile,:email,:address,:status,:c,:u)',$d+['i'=>$i,'c'=>$now,'u'=>$now]);return(int)$this->db->connection()->lastInsertId();}
    public function syncGuardianChildren(int$guardian,int$i,array$students):void{$valid=array_map('intval',$this->db->query('SELECT id FROM students WHERE institute_id=:i',['i'=>$i])->fetchAll(\PDO::FETCH_COLUMN));$ids=array_values(array_unique(array_intersect(array_map('intval',$students),$valid)));$this->db->query('DELETE gs FROM guardian_students gs JOIN guardians g ON g.id=gs.guardian_id WHERE gs.guardian_id=:g AND g.institute_id=:i',['g'=>$guardian,'i'=>$i]);foreach($ids as$n=>$student)$this->db->query('INSERT INTO guardian_students(guardian_id,student_id,is_primary,created_at) VALUES(:g,:s,:p,:c)',['g'=>$guardian,'s'=>$student,'p'=>$n===0?1:0,'c'=>date('Y-m-d H:i:s')]);}

    public function assignments(int$i):array{return$this->db->query('SELECT ta.*,e.name teacher,c.name class_name,s.name subject_name,cs.name section_name FROM teacher_assignments ta JOIN employees e ON e.id=ta.employee_id JOIN classes c ON c.id=ta.class_id LEFT JOIN subjects s ON s.id=ta.subject_id LEFT JOIN class_sections cs ON cs.id=ta.section_id WHERE ta.institute_id=:i ORDER BY e.name,c.name,s.name',['i'=>$i])->fetchAll();}
    public function saveAssignment(int$i,int$employee,int$class,?int$subject,?int$section,string$type,int$user):void{$valid=$this->db->query('SELECT 1 FROM employees e JOIN classes c ON c.id=:c AND c.institute_id=:i LEFT JOIN class_subjects x ON x.class_id=c.id WHERE e.id=:e AND e.institute_id=:i2 AND (:subject_check IS NULL OR x.subject_id=:subject_id) LIMIT 1',['c'=>$class,'i'=>$i,'e'=>$employee,'i2'=>$i,'subject_check'=>$subject,'subject_id'=>$subject])->fetchColumn();if(!$valid)throw new \DomainException('Select an institute-owned teacher and valid class subject.');if(!in_array($type,['whole_class','subject','homeroom'],true))throw new \DomainException('Select a valid assignment scope.');if($type==='subject'&&!$subject)throw new \DomainException('A subject assignment requires a subject.');$this->db->query('INSERT INTO teacher_assignments(institute_id,employee_id,class_id,subject_id,section_id,assignment_type,status,created_by,created_at,updated_at) VALUES(:i,:e,:c,:s,:section,:t,"active",:u,:n,:n2)',['i'=>$i,'e'=>$employee,'c'=>$class,'s'=>$subject,'section'=>$section,'t'=>$type,'u'=>$user,'n'=>date('Y-m-d H:i:s'),'n2'=>date('Y-m-d H:i:s')]);}
    public function deleteAssignment(int$id,int$i):bool{$q=$this->db->query('DELETE FROM teacher_assignments WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$i]);return$q->rowCount()>0;}
    public function employeeForUser(int$user,int$i):?int{$v=$this->db->query('SELECT e.id FROM employee_accounts ea JOIN employees e ON e.id=ea.employee_id WHERE ea.user_id=:u AND e.institute_id=:i',['u'=>$user,'i'=>$i])->fetchColumn();return$v?(int)$v:null;}
    public function teacherCan(int$employee,int$i,int$class,?int$subject=null):bool{return(bool)$this->db->query('SELECT 1 FROM teacher_assignments WHERE employee_id=:e AND institute_id=:i AND class_id=:c AND status="active" AND (assignment_type IN ("whole_class","homeroom") OR subject_id=:s) LIMIT 1',['e'=>$employee,'i'=>$i,'c'=>$class,'s'=>$subject])->fetchColumn();}

    public function notes(int$i,int$class=0,int$subject=0,bool$publishedOnly=false):array{$w=' WHERE n.institute_id=:i';$p=['i'=>$i];if($class){$w.=' AND n.class_id=:c';$p['c']=$class;}if($subject){$w.=' AND n.subject_id=:s';$p['s']=$subject;}if($publishedOnly)$w.=" AND n.status='published'";return$this->db->query('SELECT n.*,c.name class_name,s.name subject_name,e.name teacher FROM class_notes n JOIN classes c ON c.id=n.class_id JOIN subjects s ON s.id=n.subject_id LEFT JOIN employees e ON e.id=n.teacher_id'.$w.' ORDER BY n.publish_date DESC,n.id DESC',$p)->fetchAll();}
    public function saveNote(int$i,array$d):int{$this->db->query('INSERT INTO class_notes(institute_id,class_id,subject_id,teacher_id,chapter,title,description,attachment_path,publish_date,status,created_by,created_at,updated_at) VALUES(:i,:class_id,:subject_id,:teacher_id,:chapter,:title,:description,:attachment_path,:publish_date,:status,:created_by,:c,:u)',$d+['i'=>$i,'c'=>date('Y-m-d H:i:s'),'u'=>date('Y-m-d H:i:s')]);return(int)$this->db->connection()->lastInsertId();}
    public function deleteNote(int$id,int$i):?string{$r=$this->db->query('SELECT attachment_path FROM class_notes WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$i])->fetch();if(!$r)return null;$this->db->query('DELETE FROM class_notes WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$i]);return(string)($r['attachment_path']??'');}

    public function sessions(int$i):array{return$this->db->query('SELECT * FROM academic_sessions WHERE institute_id=:i ORDER BY start_date DESC',['i'=>$i])->fetchAll();}
    public function profiles(int$i):array{return$this->db->query('SELECT p.*,s.name session_name FROM academic_rule_profiles p LEFT JOIN academic_sessions s ON s.id=p.session_id WHERE p.institute_id=:i ORDER BY p.is_default DESC,p.name',['i'=>$i])->fetchAll();}
    public function saveSession(int$i,string$name,string$from,string$to):void{if($name===''||$from===''||$to===''||$from>$to)throw new \DomainException('Enter a valid academic session.');$this->db->query('INSERT INTO academic_sessions(institute_id,name,start_date,end_date,status,created_at,updated_at) VALUES(:i,:n,:f,:t,"active",:c,:u) ON DUPLICATE KEY UPDATE start_date=VALUES(start_date),end_date=VALUES(end_date),updated_at=VALUES(updated_at)',['i'=>$i,'n'=>$name,'f'=>$from,'t'=>$to,'c'=>date('Y-m-d H:i:s'),'u'=>date('Y-m-d H:i:s')]);}
    public function saveProfile(int$i,array$d,array$grades):int{$pdo=$this->db->connection();$pdo->beginTransaction();try{if(!empty($d['is_default']))$this->db->query('UPDATE academic_rule_profiles SET is_default=0 WHERE institute_id=:i',['i'=>$i]);$this->db->query('INSERT INTO academic_rule_profiles(institute_id,session_id,name,institute_type,board_name,min_attendance,pass_threshold,absent_counts_as_zero,is_default,effective_from,effective_to,applicable_levels,created_at,updated_at) VALUES(:i,:session_id,:name,:institute_type,:board_name,:min_attendance,:pass_threshold,:absent_counts_as_zero,:is_default,:effective_from,:effective_to,:applicable_levels,:c,:u)',$d+['i'=>$i,'c'=>date('Y-m-d H:i:s'),'u'=>date('Y-m-d H:i:s')]);$id=(int)$pdo->lastInsertId();foreach($grades as$n=>$g)$this->db->query('INSERT INTO academic_profile_grades(profile_id,label,min_percentage,max_percentage,result_status,description,sort_order) VALUES(:p,:l,:min,:max,:s,:d,:o)',['p'=>$id,'l'=>$g[0],'min'=>$g[1],'max'=>$g[2],'s'=>$g[3],'d'=>$g[4]??null,'o'=>$n]);$pdo->commit();return$id;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
    public function whatsappTemplates(int$i):array{return$this->db->query('SELECT * FROM whatsapp_templates WHERE institute_id=:i ORDER BY name',['i'=>$i])->fetchAll();}
    public function saveWhatsappTemplate(int$i,string$key,string$name,string$body):void{if(!preg_match('/^[a-z0-9_]{3,60}$/',$key)||trim($name)===''||trim($body)==='')throw new \DomainException('Enter a valid template name, key and message.');$this->db->query('INSERT INTO whatsapp_templates(institute_id,event_key,name,body,status,created_at,updated_at) VALUES(:i,:k,:n,:b,"active",:c,:u) ON DUPLICATE KEY UPDATE name=VALUES(name),body=VALUES(body),updated_at=VALUES(updated_at)',['i'=>$i,'k'=>$key,'n'=>trim($name),'b'=>trim($body),'c'=>date('Y-m-d H:i:s'),'u'=>date('Y-m-d H:i:s')]);}
    public function logWhatsapp(int$i,?int$template,string$type,?int$recipient,string$phone,string$message,int$user):void{$this->db->query('INSERT INTO whatsapp_logs(institute_id,template_id,recipient_type,recipient_id,normalized_phone,message_hash,mode,delivery_status,created_by,created_at) VALUES(:i,:t,:rt,:r,:p,:h,"click","opened",:u,:c)',['i'=>$i,'t'=>$template,'rt'=>$type,'r'=>$recipient,'p'=>$phone,'h'=>hash('sha256',$message),'u'=>$user,'c'=>date('Y-m-d H:i:s')]);}
    public function audit(int$i,int$user,string$action,string$type,?int$id,array$meta=[]):void{$this->db->query('INSERT INTO audit_logs(institute_id,user_id,action,entity_type,entity_id,metadata_json,created_at) VALUES(:i,:u,:a,:t,:id,:m,:c)',['i'=>$i,'u'=>$user?:null,'a'=>$action,'t'=>$type,'id'=>$id,'m'=>$meta?json_encode($meta,JSON_THROW_ON_ERROR):null,'c'=>date('Y-m-d H:i:s')]);}
}
